public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to a unique string key
    java.util.function.Function<int[], String> coordToKey = (int[] coord) -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    // If start equals end, travel is trivially possible
    boolean same = true;
    for (int i = 0; i < n; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] path : paths) {
            if (path.length != 2 * n) {
                // Invalid path length; skip
                continue;
            }
            int[] a = new int[n];
            int[] b = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = path[i];
                b[i] = path[n + i];
            }
            String keyA = coordToKey.apply(a);
            String keyB = coordToKey.apply(b);
            adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
            adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
        }
    }

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);

    // BFS to find if end is reachable from start
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adj.get(current);
        if (neighbors == null) continue;
        for (String neighbor : neighbors) {
            if (visited.contains(neighbor)) continue;
            if (neighbor.equals(endKey)) {
                return "can be travelled";
            }
            visited.add(neighbor);
            queue.add(neighbor);
        }
    }

    return "cannot be travelled";
}

