        freq[r]++;
    }
    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }
    // Check other remainders
    for (int r = 1; r < k; r++) {
        int complement = k - r;
        if (r > complement) {
            continue; // already checked this pair
        }
        if (freq[r] != freq[complement]) {
            return false;
        }
    }
    return true;
}

