    while (!map.isEmpty()) {
        // Ascending phase
        java.util.Map.Entry<Character, Integer> entry = map.firstEntry();
        char last = entry.getKey();
        result.append(last);
        if (entry.getValue() == 1) {
            map.remove(last);
        } else {
            map.put(last, entry.getValue() - 1);
        }
        while (true) {
            java.util.Map.Entry<Character, Integer> next = map.higherEntry(last);
            if (next == null) break;
            last = next.getKey();
            result.append(last);
            if (next.getValue() == 1) {
                map.remove(last);
            } else {
                map.put(last, next.getValue() - 1);
            }
        }
        if (map.isEmpty()) break;
        // Descending phase
        entry = map.lastEntry();
        last = entry.getKey();
        result.append(last);
        if (entry.getValue() == 1) {
            map.remove(last);
        } else {
            map.put(last, entry.getValue() - 1);
        }
        while (true) {
            java.util.Map.Entry<Character, Integer> prev = map.lowerEntry(last);
            if (prev == null) break;
            last = prev.getKey();
            result.append(last);
            if (prev.getValue() == 1) {
                map.remove(last);
            } else {
                map.put(last, prev.getValue() - 1);
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int total = 0;
    for (int num : nums) total += num;
    int maxK = n / 2;
    // dp[k][s] indicates whether a subset of size k with sum s is achievable
    boolean[][] dp = new boolean[maxK + 1][total + 1];
    dp[0][0] = true;
    for (int num : nums) {
        // iterate k in reverse to avoid using the same element multiple times
        for (int k = maxK; k >= 1; k--) {
            for (int s = total; s >= num; s--) {
                if (dp[k - 1][s - num]) {
                    dp[k][s] = true;
                }
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((total * k) % n != 0) continue;
        int target = (total * k) / n;
        if (dp[k][target]) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int prev2 = cost[0]; // cost to reach step 0
    int prev1 = cost[1]; // cost to reach step 1

    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = curr;
    }

    return Math.min(prev1, prev2);
}

