}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int sz = fib.size();
        int next = fib.get(sz - 1) + fib.get(sz - 2);
        if (next > k) break;
        fib.add(next);
    }

    // Greedy selection from largest to smallest
    int count = 0;
    int remaining = k;
    for (int i = fib.size() - 1; i >= 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
        if (remaining == 0) break;
    }
    return count;
}

public int kthFactor(int n, int k) {
