    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    Collections.reverse(large);
    List<Integer> all = new ArrayList<>(small);
    all.addAll(large);
    if (k - 1 < all.size()) {
