public String getSmallestString(int n, int k) {
    // Start with all 'a's, which gives the minimum possible sum of n
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');

    int remaining = k - n; // how much we need to add to reach the target sum

    // Increase characters from the end to keep the string lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each character can increase at most 25 (from 'a' to 'z')
        result[i] = (char) (result[i] + add);
        remaining -= add;
    }

    return new String(result);
}

